namespace{bool hasOutstandingPrefillCompute(c gv){switch(gv){case c::aL:case c::bQ:case c::aP:case c::aK:return true;default:return false;}}}q aV(const m&cT,const B&cU){const x fC=buildAdaptiveSchedulerConfig(cT,cU);const int aO=std::max(1,fC.aR);const double decode_batch_work=cT.S+N(cU.aM,aO);return{.fC=fC,.prefill_proc_curve=cU.cf,.M=cT.S,.aF=decode_batch_work/aO,.f=cT.f,};}std::vector<double>estimateCloudWorkloads(const d&cR,const q&cS){assert(cS.f>0);assert(cS.M>=0.0);assert(cS.aF>0.0);std::vector<double>workloads(cR.gL.size(),0.0);for(const bH&gu:cR.A){if(!gu.gw.has_value()||gu.gv==c::ca){continue;}const std::size_t gw=static_cast<std::size_t>(*gu.gw);assert(gw<workloads.size());workloads[gw]+=cS.aF;if(hasOutstandingPrefillCompute(gu.gv)){assert(gu.X>=0);assert(gu.X<cS.f);const double remaining_fraction=static_cast<double>(cS.f-gu.X)/cS.f;workloads[gw]+=cS.M+remaining_fraction*N(cS.prefill_proc_curve,gu.aq);}}return workloads;}std::vector<double>estimatePlacementScores(const d&cR,int rid,const q&cS){assert(rid>=0);assert(static_cast<std::size_t>(rid)<cR.A.size());const bH&gy=cR.A[static_cast<std::size_t>(rid)];assert(gy.gv==c::bP);assert(!gy.gw.has_value());std::vector<double>fG=estimateCloudWorkloads(cR,cS);const double candidate_work=cS.M+N(cS.prefill_proc_curve,gy.aq)+cS.aF;for(double&score:fG){score+=candidate_work;}return fG;}int chooseLoadAwareRemote(const d&cR,int rid,const q&cS){assert(!cR.gL.empty());const std::vector<double>fG=estimatePlacementScores(cR,rid,cS);int best_remote=rid%static_cast<int>(fG.size());for(std::size_t gw=0;gw<fG.size();++gw){if(fG[gw]<fG[static_cast<std::size_t>(best_remote)]){best_remote=static_cast<int>(gw);}}return best_remote;}std::vector<g>chooseMultiprocessorAssignments(const d&cR,int f,const q&cS){assert(f==cS.f);const T p=[&](const d&current,int rid){return chooseLoadAwareRemote(current,rid,cS);};return az(cR,f,cS.fC,p);}
